import React from 'react';
import { Languages } from 'lucide-react';
import { LANGUAGE_META, useI18n } from '../i18n';

const languageOrder = ['ar', 'fr', 'en'] as const;

const LanguageSwitcher: React.FC = () => {
  const { language, setLanguage, t } = useI18n();

  return (
    <div
      data-i18n-ignore="true"
      className="fixed left-4 top-4 z-[120] flex items-center gap-2 rounded-full border border-slate-200/80 bg-white/92 px-3 py-2 shadow-[0_16px_35px_rgba(15,23,42,0.12)] backdrop-blur"
    >
      <span className="inline-flex items-center gap-2 text-xs font-bold uppercase tracking-[0.16em] text-slate-500">
        <Languages size={14} />
        {t('Language')}
      </span>

      <div className="flex items-center gap-1 rounded-full bg-slate-100/90 p-1">
        {languageOrder.map((item) => (
          <button
            key={item}
            type="button"
            onClick={() => setLanguage(item)}
            className={`rounded-full px-3 py-1.5 text-xs font-bold transition ${
              language === item
                ? 'bg-slate-900 text-white shadow-[0_10px_22px_rgba(15,23,42,0.18)]'
                : 'text-slate-600 hover:bg-white'
            }`}
          >
            {LANGUAGE_META[item].label}
          </button>
        ))}
      </div>
    </div>
  );
};

export default LanguageSwitcher;
